import { useEffect, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { ArrowLeft, ArrowUpRight, Check, ChevronRight, Download, FileText, LayoutDashboard, LogOut, MapPin, Package, Pencil, Plus, RefreshCw, Search, Settings as SettingsIcon, ShieldCheck, ShoppingBag, Tag, Truck, Wallet, X } from 'lucide-react'
import type { AdminData, Driver, Lang, Order, OrderStatus, OrderUpdate, PaymentMethod, Product, Promotion, Settings, Zone } from '../types'
import { getAdminData, getIsAdmin, isConfigured, login, logout, resetDemo, saveDriver, savePayment, saveProduct, savePromotion, saveSettings, saveZone, subscribeAuth, updateOrder } from '../lib/api'
import { normalizePhone, transitions } from '../lib/rules'
import './admin.css'

type Tab = 'dashboard' | 'orders' | 'products' | 'zones' | 'payments' | 'promotions' | 'drivers' | 'settings'
type Props = { lang: Lang; onBack: () => void; onChange: () => void }
const statuses: OrderStatus[] = ['received', 'awaiting_payment', 'payment_confirmed', 'preparing', 'ready_for_pickup', 'out_for_delivery', 'delivered', 'cancelled']
const statusLabels: Record<OrderStatus, [string, string]> = {
  received: ['Commande reçue', 'Kòmand resevwa'], awaiting_payment: ['En attente de paiement', 'Ap tann peman'], payment_confirmed: ['Paiement confirmé', 'Peman konfime'], preparing: ['En préparation', 'Nan preparasyon'], ready_for_pickup: ['Prête pour retrait', 'Pare pou vin pran'], out_for_delivery: ['En livraison', 'Nan livrezon'], delivered: ['Livrée', 'Livre'], cancelled: ['Annulée', 'Anile'],
}
const nextStatuses = transitions
const money = (n: number) => `${new Intl.NumberFormat('fr-HT', { maximumFractionDigits: 2 }).format(n)} G`
const dateKey = (value: string) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Port-au-Prince', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(value))
const localDateTime = (value: string) => value ? new Date(new Date(value).getTime() - new Date(value).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : ''
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="adm-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function Toggle({ checked, onChange, children, disabled = false }: { checked: boolean; onChange: (checked: boolean) => void; children: ReactNode; disabled?: boolean }) { return <label className="adm-toggle"><input type="checkbox" checked={checked} onChange={e => onChange(e.target.checked)} disabled={disabled} /><span>{children}</span></label> }
function Empty({ text }: { text: string }) { return <div className="adm-empty"><Package size={32} strokeWidth={1.3} /><p>{text}</p></div> }

export default function Admin({ lang, onBack, onChange }: Props) {
  const t = (fr: string, ht: string) => lang === 'fr' ? fr : ht
  const labelStatus = (status: OrderStatus) => statusLabels[status]?.[lang === 'fr' ? 0 : 1] || status
  const [authorized, setAuthorized] = useState(!isConfigured)
  const [authLoading, setAuthLoading] = useState(isConfigured)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [data, setData] = useState<AdminData | null>(null)
  const [tab, setTab] = useState<Tab>('dashboard')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [productEdit, setProductEdit] = useState<Product | null>(null)
  const [zoneEdit, setZoneEdit] = useState<Zone | null>(null)
  const [promotionEdit, setPromotionEdit] = useState<Promotion | null>(null)
  const [driverEdit, setDriverEdit] = useState<Driver | null>(null)
  const [paymentEdit, setPaymentEdit] = useState<PaymentMethod | null>(null)
  const [settingsEdit, setSettingsEdit] = useState<Settings | null>(null)
  const [orderEdit, setOrderEdit] = useState<Order | null>(null)
  const [orderUpdate, setOrderUpdate] = useState<OrderUpdate | null>(null)
  const [productQuery, setProductQuery] = useState('')
  const [commune, setCommune] = useState('')
  const [orderStatus, setOrderStatus] = useState('')

  useEffect(() => { let live = true; if (isConfigured) getIsAdmin().then(ok => { if (live) setAuthorized(ok) }).catch(e => { if (live) setError(e instanceof Error ? e.message : t('Accès indisponible.', 'Aksè pa disponib.')) }).finally(() => { if (live) setAuthLoading(false) }); return () => { live = false } }, [])
  const refresh = async () => { const value = await getAdminData(); setData(value); setSettingsEdit(value.settings); return value }
  useEffect(() => { if (authorized) refresh().catch(e => setError(e instanceof Error ? e.message : t('Chargement impossible.', 'Nou pa ka chaje done yo.'))) }, [authorized])
  useEffect(() => { if (!isConfigured) return; return subscribeAuth(ok => { setAuthorized(ok); if (!ok) { setData(null); setOrderEdit(null); setOrderUpdate(null); setProductEdit(null); setZoneEdit(null); setPromotionEdit(null); setDriverEdit(null); setPaymentEdit(null) } }) }, [])
  useEffect(() => { if (!(productEdit || zoneEdit || promotionEdit || driverEdit || paymentEdit || orderEdit)) return; const frame = window.requestAnimationFrame(() => document.querySelector('.adm-editor')?.scrollIntoView({ block: 'start', behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' })); return () => window.cancelAnimationFrame(frame) }, [productEdit?.id, zoneEdit?.id, promotionEdit?.id, driverEdit?.id, paymentEdit?.id, orderEdit?.id])
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 5000); return () => window.clearTimeout(timer) }, [notice])
  async function act(action: () => Promise<void>, close?: () => void) {
    if (busy) return
    setBusy(true); setError(''); setNotice('')
    try { await action(); await refresh(); onChange(); close?.(); setNotice(t('Modifications enregistrées.', 'Chanjman yo anrejistre.')) } catch (e) { setError(e instanceof Error ? e.message : t('Une erreur est survenue.', 'Gen yon erè ki rive.')) } finally { setBusy(false) }
  }
  async function signIn(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await login(email, password); const ok = await getIsAdmin(); if (!ok) throw new Error(t('Ce compte ne dispose pas des droits administrateur.', 'Kont sa a pa gen dwa administratè.')); setAuthorized(true); setPassword('') } catch (e) { setError(e instanceof Error ? e.message : t('Connexion impossible.', 'Nou pa ka konekte.')) } finally { setBusy(false) } }
  async function signOut() { setBusy(true); try { await logout(); setAuthorized(false); setData(null); onBack() } catch (e) { setError(e instanceof Error ? e.message : t('Déconnexion impossible.', 'Nou pa ka dekonekte.')) } finally { setBusy(false) } }
  function openOrder(order: Order) { setOrderEdit(order); setOrderUpdate({ status: order.status, assigned_driver_id: order.assigned_driver_id, delivery_fee: order.delivery_fee, proof_note: order.proof_note || '', payment_reference: order.payment_reference || '', payment_status: order.payment_status || 'pending', note: '' }) }
  const closeEditors = () => { setProductEdit(null); setZoneEdit(null); setPromotionEdit(null); setDriverEdit(null); setPaymentEdit(null); setOrderEdit(null); setOrderUpdate(null) }
  function changeTab(next: Tab) { setTab(next); closeEditors(); setError(''); setNotice('') }
  function downloadCsv() {
    if (!data) return
    const headers = ['Référence', 'Date', 'Commune', 'Statut', 'Paiement', 'Sous-total HTG', 'Remise HTG', 'Livraison HTG', 'Total HTG', 'Coût produits HTG', 'Marge brute produits HTG']
    const rows = data.orders.map(order => { const cost = order.items.reduce((sum, line) => sum + (line.unit_cost || 0) * line.quantity, 0); return [order.reference, order.created_at, order.commune, labelStatus(order.status), order.payment_status, order.subtotal, order.discount, order.delivery_fee, order.total, cost, order.subtotal - order.discount - cost] })
    const cell = (value: unknown) => { let result = String(value ?? ''); if (/^[\s\uFEFF]*[=+\-@]|^[\t\r\n]/.test(result)) result = `'${result}`; return `"${result.replaceAll('"', '""')}"` }
    const blob = new Blob(['\ufeff' + [headers, ...rows].map(row => row.map(cell).join(';')).join('\r\n')], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `dsstore-commandes-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url)
  }
  async function invoice(order: Order) {
    if (!data) return
    setBusy(true); setError('')
    try {
      const { jsPDF } = await import('jspdf'); const pdf = new jsPDF(); let y = 25
      const line = (text: string, size = 11, bold = false) => { pdf.setFont('helvetica', bold ? 'bold' : 'normal'); pdf.setFontSize(size); for (const part of pdf.splitTextToSize(text, 170) as string[]) { if (y > 275) { pdf.addPage(); y = 20 } pdf.text(part, 20, y); y += size * .5 + 3 } }
      pdf.setTextColor(23, 79, 70); line(data.settings.name || 'DS STORE', 25, true); pdf.setTextColor(40, 48, 44)
      line(t(isConfigured ? 'Facture de commande' : 'Facture de démonstration — sans valeur commerciale', isConfigured ? 'Fakti kòmand' : 'Fakti demonstrasyon — pa gen valè komèsyal'), 12, true)
      line(`${t('Référence', 'Referans')} : ${order.reference}`); line(`${t('Date', 'Dat')} : ${new Date(order.created_at).toLocaleString(lang === 'fr' ? 'fr-HT' : 'fr-HT')}`)
      if (data.settings.pickup_address) line(data.settings.pickup_address)
      if (data.settings.whatsapp) line(`WhatsApp : ${data.settings.whatsapp}`)
      y += 5; line(`${t('Client', 'Kliyan')} : ${order.customer_name}`); if (order.phone) line(order.phone); if (order.address) line(`${order.commune} — ${order.address}`); if (order.landmark) line(`${t('Repère', 'Pwen referans')} : ${order.landmark}`)
      y += 5; line(t('DÉTAIL DE LA COMMANDE', 'DETAY KÒMAND LAN'), 12, true)
      for (const item of order.items) line(`${item.quantity} × ${item.name} | ${money(item.unit_price)} | ${money(item.quantity * item.unit_price)}`)
      y += 5; line(`${t('Sous-total', 'Soutotal')} : ${money(order.subtotal)}`); line(`${t('Remise', 'Rabè')} : ${money(order.discount)}`); line(`${t('Livraison', 'Livrezon')} : ${money(order.delivery_fee)}`); line(`TOTAL : ${money(order.total)}`, 16, true)
      y += 3; line(`${t('Statut', 'Eta')} : ${labelStatus(order.status)}`); line(`${t('Paiement', 'Peman')} : ${order.payment_status === 'confirmed' ? t('Confirmé', 'Konfime') : order.payment_status === 'refunded' ? t('Remboursé', 'Ranbouse') : t('À confirmer', 'Pou konfime')}`); if (order.payment_reference) line(`${t('Référence de paiement', 'Referans peman')} : ${order.payment_reference}`)
      line(t('Devise : gourde haïtienne (HTG).', 'Lajan : goud ayisyen (HTG).'), 9); if (!isConfigured) line(t('Document de test. Aucun paiement réel.', 'Dokiman tès. Pa gen peman reyèl.'), 9)
      pdf.save(`${order.reference.replace(/[^a-z0-9_-]/gi, '_')}.pdf`)
    } catch { setError(t('Le PDF n’a pas pu être généré. Réessaie.', 'Nou pa ka fè PDF la. Eseye ankò.')) } finally { setBusy(false) }
  }

  const tabs: { id: Tab; fr: string; ht: string; icon: typeof Package }[] = [{ id: 'dashboard', fr: 'Vue d’ensemble', ht: 'Apèsi', icon: LayoutDashboard }, { id: 'orders', fr: 'Commandes', ht: 'Kòmand', icon: ShoppingBag }, { id: 'products', fr: 'Produits', ht: 'Pwodwi', icon: Package }, { id: 'zones', fr: 'Livraison', ht: 'Livrezon', icon: MapPin }, { id: 'payments', fr: 'Paiements', ht: 'Peman', icon: Wallet }, { id: 'promotions', fr: 'Promotions', ht: 'Pwomosyon', icon: Tag }, { id: 'drivers', fr: 'Livreurs', ht: 'Livre', icon: Truck }, { id: 'settings', fr: 'Boutique', ht: 'Boutik', icon: SettingsIcon }]
  const title = tabs.find(item => item.id === tab)
  const submit = (text = t('Enregistrer', 'Anrejistre')) => <button type="submit" className="adm-primary" disabled={busy}>{busy ? <RefreshCw size={16} className="adm-spin" /> : <Check size={16} />}{busy ? t('Enregistrement…', 'Ap anrejistre…') : text}</button>
  const editorHeading = (text: string) => <div className="adm-editor-heading"><h3>{text}</h3><button type="button" className="adm-icon" onClick={closeEditors} aria-label={t('Fermer le formulaire', 'Fèmen fòm nan')}><X size={20} /></button></div>
  const errorBox = error && <div className="adm-alert adm-error" role="alert">{error}</div>
  if (authLoading) return <div className="adm-auth"><RefreshCw className="adm-spin" /><p>{t('Vérification de l’accès…', 'Ap verifye aksè…')}</p></div>
  if (!authorized) return <div className="adm-auth"><button onClick={onBack} className="adm-back"><ArrowLeft size={17} />{t('Retour à la boutique', 'Retounen nan boutik la')}</button><form className="adm-login" onSubmit={signIn}><ShieldCheck size={34} /><h1>{t('Espace administration', 'Espas administrasyon')}</h1><p>{t('Connecte-toi avec un compte administrateur autorisé.', 'Konekte ak yon kont administratè ki otorize.')}</p>{errorBox}<Field label={t('Adresse e-mail', 'Adrès imel')}><input type="email" autoComplete="username" required value={email} onChange={e => setEmail(e.target.value)} /></Field><Field label={t('Mot de passe', 'Modpas')}><input type="password" autoComplete="current-password" required value={password} onChange={e => setPassword(e.target.value)} /></Field>{submit(t('Se connecter', 'Konekte'))}</form></div>
  if (!data) return <div className="adm-auth"><button className="adm-back" onClick={onBack}><ArrowLeft size={18} />{t('Boutique', 'Boutik')}</button>{errorBox || <><RefreshCw className="adm-spin" /><p>{t('Chargement de la boutique…', 'Ap chaje boutik la…')}</p></>}<button className="adm-secondary" onClick={() => void refresh().catch(e => setError(e instanceof Error ? e.message : 'Erreur'))}>{t('Réessayer', 'Eseye ankò')}</button></div>

  const today = dateKey(new Date().toISOString()); const todayOrders = data.orders.filter(order => dateKey(order.created_at) === today)
  const paidToday = todayOrders.filter(order => order.payment_status === 'confirmed' && order.status !== 'cancelled')
  const todaySales = paidToday.reduce((sum, order) => sum + order.total, 0)
  const todayMargin = paidToday.reduce((sum, order) => sum + order.subtotal - order.discount - order.items.reduce((cost, line) => cost + (line.unit_cost || 0) * line.quantity, 0), 0)
  const unknownCosts = paidToday.some(order => order.items.some(line => line.unit_cost === undefined))
  const filteredOrders = [...data.orders].sort((a, b) => b.created_at.localeCompare(a.created_at)).filter(order => (!commune || order.commune === commune) && (!orderStatus || order.status === orderStatus))
  const filteredProducts = data.products.filter(product => `${product.name_fr} ${product.name_ht} ${product.slug}`.toLowerCase().includes(productQuery.toLowerCase()))

  return <div className="adm-shell">
    <aside className="adm-sidebar"><button className="adm-brand" onClick={onBack}><span className="adm-logo">DS</span><span>DS STORE<small>{t('Administration', 'Administrasyon')}</small></span></button><nav aria-label={t('Administration', 'Administrasyon')}>{tabs.map(item => <button key={item.id} className={tab === item.id ? 'adm-nav active' : 'adm-nav'} onClick={() => changeTab(item.id)} aria-current={tab === item.id ? 'page' : undefined}><item.icon size={19} /><span>{t(item.fr, item.ht)}</span>{item.id === 'orders' && data.orders.filter(order => !['delivered', 'cancelled'].includes(order.status)).length > 0 && <b>{data.orders.filter(order => !['delivered', 'cancelled'].includes(order.status)).length}</b>}</button>)}</nav><div className="adm-sidebar-bottom"><span className="adm-sidebar-caption">LES CAYES · HAÏTI</span><button onClick={onBack}><ArrowUpRight size={18} />{t('Voir la boutique', 'Wè boutik la')}</button>{isConfigured && <button onClick={() => void signOut()} disabled={busy}><LogOut size={17} />{t('Déconnexion', 'Dekonekte')}</button>}</div></aside>
    <main className="adm-main"><header className="adm-topbar"><div><span className="adm-eyebrow">DS STORE / {t('GESTION', 'JESYON')}</span><h1>{title && t(title.fr, title.ht)}</h1></div><div className="adm-topbar-actions"><span className={isConfigured ? 'adm-live' : 'adm-demo-tag'}><span />{isConfigured ? t('Boutique connectée', 'Boutik konekte') : t('Mode démonstration', 'Mòd demonstrasyon')}</span><button className="adm-icon" onClick={() => void act(async () => {})} disabled={busy} aria-label={t('Actualiser', 'Rafrechi')}><RefreshCw size={18} className={busy ? 'adm-spin' : ''} /></button></div></header>
    {!isConfigured && <div className="adm-demo-banner"><ShieldCheck size={20} /><div><strong>{t('Administration de démonstration', 'Administrasyon demonstrasyon')}</strong><p>{t('Modifications enregistrées uniquement dans ce navigateur. Aucune commande réelle. Ne saisis pas de données personnelles réelles.', 'Chanjman yo rete sèlman nan navigatè sa a. Pa gen kòmand reyèl. Pa antre enfòmasyon pèsonèl reyèl.')}</p></div></div>}
    {errorBox}{notice && <div className="adm-alert adm-success" role="status"><Check size={17} />{notice}</div>}

    {tab === 'dashboard' && <>
      <div className="adm-section-heading"><div><h2>{t('Un œil sur votre activité.', 'Yon kout je sou aktivite w.')}</h2><p>{new Date().toLocaleDateString(lang === 'fr' ? 'fr-HT' : 'fr-HT', { dateStyle: 'full', timeZone: 'America/Port-au-Prince' })} · {t('heure d’Haïti', 'lè Ayiti')}</p></div><button className="adm-secondary" onClick={downloadCsv} disabled={!data.orders.length}><Download size={16} />{t('Exporter les rapports', 'Ekspòte rapò yo')}</button></div>
      <div className="adm-stats"><article><span>{t('Ventes du jour', 'Lavant jounen an')}</span><strong>{money(todaySales)}</strong><small>{t('Commandes du jour payées et non annulées', 'Kòmand jodi a ki peye epi ki pa anile')}</small></article><article><span>{t('Commandes du jour', 'Kòmand jounen an')}</span><strong>{todayOrders.length.toString().padStart(2, '0')}</strong><small>{t('Tous les statuts', 'Tout eta yo')}</small></article><article><span>{t('Marge brute produits', 'Maj brit pwodwi yo')}</span><strong>{money(todayMargin)}</strong><small>{unknownCosts ? t('Certains coûts ne sont pas renseignés', 'Gen pri acha ki pa ranpli') : t('Hors livraison et frais opérationnels', 'San livrezon ak depans operasyon')}</small></article><article><span>{t('Zones actives', 'Zòn aktif')}</span><strong>{data.zones.filter(zone => zone.active).length.toString().padStart(2, '0')}</strong><small>{t('Sur', 'Sou')} {data.zones.length} {t('zones configurées', 'zòn ki konfigire')}</small></article></div>
      <div className="adm-dashboard-grid"><section className="adm-panel"><div className="adm-panel-heading"><h3>{t('Dernières commandes', 'Dènye kòmand yo')}</h3><button className="adm-text-btn" onClick={() => changeTab('orders')}>{t('Tout voir', 'Wè tout')}<ChevronRight size={15} /></button></div>{data.orders.length ? <div className="adm-compact-orders">{[...data.orders].sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, 5).map(order => <button key={order.id} onClick={() => { changeTab('orders'); openOrder(order) }}><span><strong>{order.reference}</strong><small>{order.commune || t('Retrait', 'Vin pran')}</small></span><span><strong>{money(order.total)}</strong><small>{labelStatus(order.status)}</small></span><ChevronRight size={17} /></button>)}</div> : <Empty text={t('Les commandes apparaîtront ici dès le premier achat.', 'Kòmand yo ap parèt la depi premye acha a.')} />}</section><section className="adm-panel"><div className="adm-panel-heading"><h3>{t('À préparer', 'Pou prepare')}</h3><span className="adm-soft-badge">{t('Boutique', 'Boutik')}</span></div><div className="adm-checklist">{[{ done: Boolean(data.products.some(product => product.active)), fr: 'Ajouter votre catalogue', ht: 'Ajoute katalòg ou', target: 'products' as Tab }, { done: Boolean(data.settings.whatsapp), fr: 'Renseigner le WhatsApp', ht: 'Ranpli WhatsApp la', target: 'settings' as Tab }, { done: data.zones.some(zone => zone.active) || data.settings.pickup_enabled, fr: 'Configurer livraison ou retrait', ht: 'Konfigire livrezon oswa vin pran', target: 'zones' as Tab }, { done: data.payments.some(payment => payment.enabled), fr: 'Activer un moyen de paiement', ht: 'Aktive yon fason pou peye', target: 'payments' as Tab }].map(item => <button key={item.fr} onClick={() => changeTab(item.target)}><span className={item.done ? 'adm-check-circle done' : 'adm-check-circle'}>{item.done && <Check size={13} />}</span>{t(item.fr, item.ht)}<ChevronRight size={16} /></button>)}</div></section></div>
      <section className="adm-panel"><div className="adm-panel-heading"><h3>{t('Stock à surveiller', 'Stòk pou siveye')}</h3></div>{data.products.filter(product => product.active && product.stock <= 5).length ? <div className="adm-stock-list">{data.products.filter(product => product.active && product.stock <= 5).map(product => <button key={product.id} onClick={() => { changeTab('products'); setProductEdit({ ...product }) }}><span>{lang === 'fr' ? product.name_fr : product.name_ht}</span><span className={product.stock === 0 ? 'adm-badge danger' : 'adm-badge warning'}>{product.stock} {t('en stock', 'nan stòk')}</span><Pencil size={15} /></button>)}</div> : <p className="adm-panel-note">{t('Aucune alerte de stock.', 'Pa gen alèt stòk.')}</p>}</section>
    </>}

    {tab === 'products' && <>
      <div className="adm-section-heading"><div><h2>{t('Le bon produit, au bon prix.', 'Bon pwodwi, bon pri.')}</h2><p>{data.products.length} {t('produits dans votre catalogue', 'pwodwi nan katalòg ou')}</p></div><button className="adm-primary" onClick={() => setProductEdit({ id: crypto.randomUUID(), slug: '', name_fr: '', name_ht: '', description_fr: '', description_ht: '', category_id: data.categories[0]?.id || '', image_url: '', price: 0, cost_price: 0, stock: 0, active: false, featured: false, is_new: true, promotion_price: null })}><Plus size={17} />{t('Ajouter un produit', 'Ajoute yon pwodwi')}</button></div>
      {productEdit && <form className="adm-editor" onSubmit={e => { e.preventDefault(); const p = productEdit; if (p.promotion_price !== null && p.promotion_price >= p.price) { setError(t('Le prix promotionnel doit être inférieur au prix normal.', 'Pri pwomosyon an dwe pi ba pase pri nòmal la.')); return } void act(() => saveProduct(p), () => setProductEdit(null)) }}>{editorHeading(t('Fiche produit', 'Fich pwodwi'))}<div className="adm-form-grid"><Field label={t('Nom français', 'Non franse')}><input required maxLength={160} value={productEdit.name_fr} onChange={e => setProductEdit({ ...productEdit, name_fr: e.target.value })} /></Field><Field label={t('Nom créole', 'Non kreyòl')}><input required maxLength={160} value={productEdit.name_ht} onChange={e => setProductEdit({ ...productEdit, name_ht: e.target.value })} /></Field><Field label={t('Identifiant du lien', 'Idantifyan lyen an')} hint={t('Exemple : sac-a-dos-urbain', 'Egzanp : sak-lekol')}><input required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxLength={160} value={productEdit.slug} onChange={e => setProductEdit({ ...productEdit, slug: e.target.value.toLowerCase() })} /></Field><Field label={t('Catégorie', 'Kategori')}><select required value={productEdit.category_id} onChange={e => setProductEdit({ ...productEdit, category_id: e.target.value })}>{data.categories.map(category => <option key={category.id} value={category.id}>{lang === 'fr' ? category.name_fr : category.name_ht}</option>)}</select></Field><Field label={t('Prix de vente (G)', 'Pri vant (G)')}><input type="number" min="0.01" step="0.01" required value={productEdit.price} onChange={e => setProductEdit({ ...productEdit, price: Number(e.target.value) })} /></Field><Field label={t('Coût d’achat (G)', 'Pri acha (G)')} hint={t('Privé. Utilisé pour calculer la marge.', 'Prive. Pou kalkile maj la.')}><input type="number" min="0" step="0.01" required value={productEdit.cost_price ?? 0} onChange={e => setProductEdit({ ...productEdit, cost_price: Number(e.target.value) })} /></Field><Field label={t('Quantité en stock', 'Kantite nan stòk')}><input type="number" min="0" step="1" required value={productEdit.stock} onChange={e => setProductEdit({ ...productEdit, stock: Number(e.target.value) })} /></Field><Field label={t('Prix promotionnel (G)', 'Pri pwomosyon (G)')} hint={t('Laisser vide sans réduction.', 'Kite vid si pa gen rabè.')}><input type="number" min="0.01" step="0.01" value={productEdit.promotion_price ?? ''} onChange={e => setProductEdit({ ...productEdit, promotion_price: e.target.value === '' ? null : Number(e.target.value) })} /></Field><Field label={t('Description française', 'Deskripsyon franse')}><textarea required rows={3} maxLength={3000} value={productEdit.description_fr} onChange={e => setProductEdit({ ...productEdit, description_fr: e.target.value })} /></Field><Field label={t('Description créole', 'Deskripsyon kreyòl')}><textarea required rows={3} maxLength={3000} value={productEdit.description_ht} onChange={e => setProductEdit({ ...productEdit, description_ht: e.target.value })} /></Field><Field label={t('Adresse de l’image', 'Adrès imaj la')} hint={t('Lien HTTPS ou chemin /images/…', 'Lyen HTTPS oswa chemen /images/…')}><input required value={productEdit.image_url} maxLength={1500} onChange={e => setProductEdit({ ...productEdit, image_url: e.target.value })} /></Field><div className="adm-toggle-group"><Toggle checked={productEdit.active} onChange={active => setProductEdit({ ...productEdit, active })}>{t('Visible en boutique', 'Vizib nan boutik')}</Toggle><Toggle checked={productEdit.featured} onChange={featured => setProductEdit({ ...productEdit, featured })}>{t('Produit populaire', 'Pwodwi popilè')}</Toggle><Toggle checked={productEdit.is_new} onChange={is_new => setProductEdit({ ...productEdit, is_new })}>{t('Nouveauté', 'Nouvo')}</Toggle></div></div><div className="adm-form-actions"><button type="button" className="adm-secondary" onClick={() => setProductEdit(null)}>{t('Annuler', 'Anile')}</button>{submit()}</div></form>}
      <section className="adm-panel"><div className="adm-table-toolbar"><label className="adm-search"><Search size={17} /><input aria-label={t('Rechercher un produit', 'Chèche yon pwodwi')} placeholder={t('Rechercher un produit…', 'Chèche yon pwodwi…')} value={productQuery} onChange={e => setProductQuery(e.target.value)} /></label><span>{filteredProducts.length} {t('résultats', 'rezilta')}</span></div><div className="adm-table-scroll"><table><thead><tr><th>{t('Produit', 'Pwodwi')}</th><th>{t('Prix', 'Pri')}</th><th>{t('Coût', 'Pri acha')}</th><th>{t('Stock', 'Stòk')}</th><th>{t('Visibilité', 'Vizibilite')}</th><th><span className="adm-sr-only">{t('Action', 'Aksyon')}</span></th></tr></thead><tbody>{filteredProducts.map(product => <tr key={product.id}><td><div className="adm-product-cell"><img src={product.image_url} alt="" loading="lazy" /><div><strong>{lang === 'fr' ? product.name_fr : product.name_ht}</strong><small>{data.categories.find(category => category.id === product.category_id)?.[lang === 'fr' ? 'name_fr' : 'name_ht'] || '—'}</small></div></div></td><td><strong>{money(product.promotion_price ?? product.price)}</strong>{product.promotion_price !== null && <small className="adm-strike">{money(product.price)}</small>}</td><td>{money(product.cost_price ?? 0)}</td><td><span className={`adm-badge ${product.stock === 0 ? 'danger' : product.stock <= 5 ? 'warning' : ''}`}>{product.stock}</span></td><td><span className={`adm-badge ${product.active ? 'success' : ''}`}>{product.active ? t('Actif', 'Aktif') : t('Masqué', 'Kache')}</span></td><td><button className="adm-icon" onClick={() => setProductEdit({ ...product })} aria-label={`${t('Modifier', 'Modifye')} ${product.name_fr}`}><Pencil size={16} /></button></td></tr>)}</tbody></table></div>{!filteredProducts.length && <Empty text={t('Aucun produit trouvé.', 'Pa gen pwodwi ki jwenn.')} />}</section>
    </>}

    {tab === 'zones' && <>
      <div className="adm-section-heading"><div><h2>{t('La proximité se prépare.', 'Pwoksimite mande preparasyon.')}</h2><p>{t('Seules les zones activées sont proposées aux clients.', 'Se sèlman zòn ki aktive yo kliyan yo ka chwazi.')}</p></div><button className="adm-primary" onClick={() => setZoneEdit({ id: crypto.randomUUID(), department: 'Sud', commune: '', name: '', active: false, fee: 0, estimated_time: '', min_order: 0, conditions: '' })}><Plus size={17} />{t('Ajouter une zone', 'Ajoute yon zòn')}</button></div>
      {zoneEdit && <form className="adm-editor" onSubmit={e => { e.preventDefault(); void act(() => saveZone(zoneEdit), () => setZoneEdit(null)) }}>{editorHeading(t('Configurer la zone', 'Konfigire zòn nan'))}<div className="adm-form-grid"><Field label={t('Département', 'Depatman')}><input required maxLength={100} value={zoneEdit.department} onChange={e => setZoneEdit({ ...zoneEdit, department: e.target.value })} /></Field><Field label={t('Commune', 'Komin')}><input required maxLength={100} value={zoneEdit.commune} onChange={e => setZoneEdit({ ...zoneEdit, commune: e.target.value })} /></Field><Field label={t('Zone / quartier', 'Zòn / katye')}><input required maxLength={140} value={zoneEdit.name} onChange={e => setZoneEdit({ ...zoneEdit, name: e.target.value })} /></Field><Field label={t('Frais de livraison (G)', 'Frè livrezon (G)')}><input required type="number" min="0" step="0.01" value={zoneEdit.fee} onChange={e => setZoneEdit({ ...zoneEdit, fee: Number(e.target.value) })} /></Field><Field label={t('Délai estimé', 'Tan estime')} hint={t('Exemple : 24 à 48 heures après confirmation', 'Egzanp : 24 a 48 èdtan apre konfimasyon')}><input required maxLength={200} value={zoneEdit.estimated_time} onChange={e => setZoneEdit({ ...zoneEdit, estimated_time: e.target.value })} /></Field><Field label={t('Minimum de commande (G)', 'Kòmand minimòm (G)')}><input type="number" required min="0" step="0.01" value={zoneEdit.min_order} onChange={e => setZoneEdit({ ...zoneEdit, min_order: Number(e.target.value) })} /></Field><Field label={t('Conditions de livraison', 'Kondisyon livrezon')}><textarea required rows={3} maxLength={2000} value={zoneEdit.conditions} onChange={e => setZoneEdit({ ...zoneEdit, conditions: e.target.value })} /></Field><div className="adm-toggle-group"><Toggle checked={zoneEdit.active} onChange={active => setZoneEdit({ ...zoneEdit, active })}>{t('Activer cette zone de livraison', 'Aktive zòn livrezon sa a')}</Toggle><p className="adm-help">{t('L’activation rend cette zone disponible au passage de commande.', 'Lè ou aktive zòn sa a, kliyan yo ka chwazi li nan kòmand yo.')}</p></div></div><div className="adm-form-actions"><button type="button" className="adm-secondary" onClick={() => setZoneEdit(null)}>{t('Annuler', 'Anile')}</button>{submit()}</div></form>}
      <div className="adm-zones-grid">{data.zones.map(zone => <article className="adm-zone-card" key={zone.id}><div className="adm-zone-top"><span className="adm-zone-icon"><MapPin size={21} /></span><span className={`adm-badge ${zone.active ? 'success' : ''}`}>{zone.active ? t('Active', 'Aktif') : t('Inactive', 'Inaktif')}</span></div><small>{zone.department}</small><h3>{zone.commune}</h3><p>{zone.name}</p><dl><div><dt>{t('Livraison', 'Livrezon')}</dt><dd>{money(zone.fee)}</dd></div><div><dt>{t('Minimum', 'Minimòm')}</dt><dd>{money(zone.min_order)}</dd></div><div><dt>{t('Délai', 'Tan')}</dt><dd>{zone.estimated_time || t('À définir', 'Pou defini')}</dd></div></dl>{zone.conditions && <p className="adm-zone-conditions">{zone.conditions}</p>}<button className="adm-secondary" onClick={() => setZoneEdit({ ...zone })}><Pencil size={15} />{t('Configurer', 'Konfigire')}</button></article>)}</div>
    </>}

    {tab === 'orders' && <>
      <div className="adm-section-heading"><div><h2>{t('Chaque commande compte.', 'Chak kòmand konte.')}</h2><p>{t('Suivi, paiement et remise : toute l’opération au même endroit.', 'Swivi, peman ak remiz : tout operasyon an menm kote.')}</p></div><button className="adm-secondary" onClick={downloadCsv} disabled={!data.orders.length}><Download size={16} />{t('Exporter CSV', 'Ekspòte CSV')}</button></div>
      <section className="adm-panel"><div className="adm-table-toolbar"><div className="adm-filters"><Field label={t('Commune', 'Komin')}><select value={commune} onChange={e => setCommune(e.target.value)}><option value="">{t('Toutes les communes', 'Tout komin yo')}</option>{[...new Set(data.orders.map(order => order.commune).filter(Boolean))].map(value => <option key={value}>{value}</option>)}</select></Field><Field label={t('Statut', 'Eta')}><select value={orderStatus} onChange={e => setOrderStatus(e.target.value)}><option value="">{t('Tous les statuts', 'Tout eta yo')}</option>{statuses.map(value => <option value={value} key={value}>{labelStatus(value)}</option>)}</select></Field></div><span>{filteredOrders.length} {t('commandes', 'kòmand')}</span></div><div className="adm-table-scroll"><table><thead><tr><th>{t('Référence', 'Referans')}</th><th>{t('Client / commune', 'Kliyan / komin')}</th><th>{t('Montant', 'Montan')}</th><th>{t('Statut', 'Eta')}</th><th>{t('Date', 'Dat')}</th><th><span className="adm-sr-only">{t('Consulter', 'Konsilte')}</span></th></tr></thead><tbody>{filteredOrders.map(order => <tr key={order.id}><td><strong>{order.reference}</strong></td><td>{order.customer_name}<small>{order.commune || t('Retrait', 'Vin pran')}</small></td><td>{money(order.total)}</td><td><span className={`adm-badge ${order.status === 'delivered' ? 'success' : order.status === 'cancelled' ? 'danger' : 'warning'}`}>{labelStatus(order.status)}</span></td><td>{new Date(order.created_at).toLocaleDateString('fr-HT')}</td><td><button className="adm-icon" aria-label={`${t('Consulter', 'Konsilte')} ${order.reference}`} onClick={() => openOrder(order)}><ChevronRight size={18} /></button></td></tr>)}</tbody></table></div>{!filteredOrders.length && <Empty text={t('Aucune commande pour ces filtres.', 'Pa gen kòmand pou filt sa yo.')} />}</section>
      {orderEdit && orderUpdate && <section className="adm-editor">{editorHeading(`${t('Commande', 'Kòmand')} ${orderEdit.reference}`)}<div className="adm-order-summary"><div><span>{t('Client', 'Kliyan')}</span><strong>{orderEdit.customer_name}</strong><p>{orderEdit.phone}</p><p>{orderEdit.fulfillment === 'pickup' ? t('Retrait en boutique', 'Vin pran nan boutik') : `${orderEdit.commune} — ${orderEdit.address}`}</p>{orderEdit.landmark && <p>{t('Repère', 'Pwen referans')} : {orderEdit.landmark}</p>}</div><div><span>{t('Montant actuel', 'Montan aktyèl')}</span><strong>{money(orderEdit.total)}</strong><p>{t('Paiement', 'Peman')} : {orderEdit.payment_method.toUpperCase()}</p><button className="adm-secondary" disabled={busy} onClick={() => void invoice(orderEdit)}><FileText size={16} />{t('Facture PDF', 'Fakti PDF')}</button></div></div><div className="adm-order-lines">{orderEdit.items.map((item, index) => <div key={`${item.product_id}-${index}`}><span>{item.quantity} × {item.name}</span><strong>{money(item.quantity * item.unit_price)}</strong></div>)}<div><span>{t('Remise', 'Rabè')}</span><strong>− {money(orderEdit.discount)}</strong></div><div><span>{t('Livraison', 'Livrezon')}</span><strong>{money(orderEdit.delivery_fee)}</strong></div></div>
      <form onSubmit={e => { e.preventDefault(); if (orderUpdate.status === 'cancelled' && orderEdit.payment_status === 'confirmed' && orderUpdate.payment_status !== 'refunded') { setError(t('Vérifie le remboursement, puis sélectionne « Remboursé » avant de clôturer cette commande payée.', 'Verifye ranbousman an, epi chwazi « Ranbouse » anvan ou fèmen kòmand ki peye sa a.')); return } if (orderUpdate.status === 'delivered' && orderUpdate.proof_note.trim().length < 5) { setError(t('Une preuve de remise est obligatoire pour confirmer la livraison.', 'Yon prèv remiz obligatwa pou konfime livrezon an.')); return } void act(() => updateOrder(orderEdit.id, orderUpdate), () => { setOrderEdit(null); setOrderUpdate(null) }) }}><div className="adm-form-grid"><Field label={t('Nouveau statut', 'Nouvo eta')}><select value={orderUpdate.status} onChange={e => setOrderUpdate({ ...orderUpdate, status: e.target.value as OrderStatus })}>{[orderEdit.status, ...nextStatuses[orderEdit.status]].filter(status => !(orderEdit.fulfillment === 'pickup' && status === 'out_for_delivery') && !(orderEdit.fulfillment === 'delivery' && status === 'ready_for_pickup')).map(status => <option value={status} key={status}>{labelStatus(status)}</option>)}</select></Field><Field label={t('Livreur affecté', 'Livre ki responsab')}><select value={orderUpdate.assigned_driver_id || ''} disabled={orderEdit.fulfillment === 'pickup' || ['delivered', 'cancelled'].includes(orderEdit.status)} onChange={e => setOrderUpdate({ ...orderUpdate, assigned_driver_id: e.target.value || null })}><option value="">{t('Non affecté', 'Poko bay')}</option>{data.drivers.filter(driver => driver.active || driver.id === orderEdit.assigned_driver_id).map(driver => <option value={driver.id} key={driver.id}>{driver.name}{!driver.active ? t(' (inactif)', ' (inaktif)') : ''}</option>)}</select></Field><Field label={t('Frais de livraison (G)', 'Frè livrezon (G)')} hint={t('Le total est recalculé à l’enregistrement.', 'Total la ap rekalkile lè ou anrejistre.')}><input type="number" required min="0" step="0.01" disabled={orderEdit.fulfillment === 'pickup' || ['delivered', 'cancelled'].includes(orderEdit.status)} value={orderUpdate.delivery_fee} onChange={e => setOrderUpdate({ ...orderUpdate, delivery_fee: Number(e.target.value) })} /></Field><Field label={t('État du paiement', 'Eta peman')}><select value={orderUpdate.payment_status} disabled={['delivered', 'cancelled'].includes(orderEdit.status)} onChange={e => setOrderUpdate({ ...orderUpdate, payment_status: e.target.value })}><option value="pending" disabled={orderEdit.payment_status === 'confirmed'}>{t('En attente', 'Ap tann')}</option><option value="confirmed">{t('Confirmé après vérification', 'Konfime apre verifikasyon')}</option><option value="refunded" disabled={orderUpdate.status !== 'cancelled' || orderEdit.payment_status !== 'confirmed'}>{t('Remboursé', 'Ranbouse')}</option></select></Field><Field label={t('Référence de paiement', 'Referans peman')} hint={t('Vérifier le paiement avant de le confirmer.', 'Verifye peman an anvan ou konfime li.')}><input maxLength={200} value={orderUpdate.payment_reference} disabled={['delivered', 'cancelled'].includes(orderEdit.status)} onChange={e => setOrderUpdate({ ...orderUpdate, payment_reference: e.target.value })} /></Field><Field label={t('Preuve de remise', 'Prèv remiz')} hint={t('Nom du destinataire, date et détails de la remise.', 'Non moun ki resevwa a, dat ak detay remiz la.')}><textarea rows={2} maxLength={2000} minLength={5} required={orderUpdate.status === 'delivered'} disabled={['delivered', 'cancelled'].includes(orderEdit.status)} value={orderUpdate.proof_note} onChange={e => setOrderUpdate({ ...orderUpdate, proof_note: e.target.value })} /></Field><Field label={t('Note d’opération', 'Nòt operasyon')}><textarea rows={2} maxLength={1000} disabled={['delivered', 'cancelled'].includes(orderEdit.status)} value={orderUpdate.note} onChange={e => setOrderUpdate({ ...orderUpdate, note: e.target.value })} /></Field></div>{orderUpdate.status === 'cancelled' && orderEdit.payment_status === 'confirmed' && <p className="adm-refund-note">{t('Vérifiez le remboursement avant de clôturer cette commande payée.', 'Verifye ranbousman an anvan ou fèmen kòmand ki peye sa a.')}</p>}<div className="adm-form-actions"><span className="adm-help">{t('Chaque modification est ajoutée à l’historique.', 'Chak chanjman ajoute nan istorik la.')}</span>{!['delivered', 'cancelled'].includes(orderEdit.status) && submit(t('Mettre à jour la commande', 'Mete kòmand lan ajou'))}</div></form><h4>{t('Historique des opérations', 'Istorik operasyon yo')}</h4><ol className="adm-timeline">{orderEdit.events.length ? [...orderEdit.events].sort((a, b) => a.created_at.localeCompare(b.created_at)).map(event => <li key={event.id}><span /><div><strong>{labelStatus(event.status)}</strong><small>{new Date(event.created_at).toLocaleString('fr-HT')}</small>{event.note && <p>{event.note}</p>}</div></li>) : <li><p>{t('Aucune opération enregistrée.', 'Pa gen operasyon anrejistre.')}</p></li>}</ol></section>}
    </>}

    {tab === 'payments' && <><div className="adm-section-heading"><div><h2>{t('Des paiements bien encadrés.', 'Peman ki byen kontwole.')}</h2><p>{t('Aucun encaissement électronique sans configuration et validation technique.', 'Pa gen peman elektwonik san konfigirasyon ak validasyon teknik.')}</p></div></div><div className="adm-payment-grid">{data.payments.map(payment => { const electronic = payment.id === 'moncash' || payment.id === 'natcash'; return <article key={payment.id} className="adm-panel adm-payment-card"><div className="adm-payment-card-top"><span className={`adm-payment-symbol ${payment.id}`}>{payment.id === 'moncash' ? 'M' : payment.id === 'natcash' ? 'N' : <Wallet size={23} />}</span><span className={`adm-badge ${payment.enabled ? 'success' : ''}`}>{payment.enabled ? t('Actif', 'Aktif') : t('Inactif', 'Inaktif')}</span></div><h3>{payment.label}</h3><p>{electronic ? t('Intégration à connecter et tester côté serveur. Activation indisponible dans cette version.', 'Entegrasyon pou konekte epi teste bò sèvè. Aktivasyon pa disponib nan vèsyon sa a.') : payment.id === 'cod' ? t('Le client règle son achat au moment de la remise.', 'Kliyan an peye lè li resevwa kòmand lan.') : t('Le paiement est contrôlé et confirmé manuellement par l’administration.', 'Administrasyon an verifye epi konfime peman an manyèlman.')}</p>{!electronic && <button className="adm-secondary" onClick={() => setPaymentEdit({ ...payment })}><SettingsIcon size={15} />{t('Configurer', 'Konfigire')}</button>}{electronic && <span className="adm-locked"><ShieldCheck size={15} />{t('Validation technique requise', 'Validasyon teknik obligatwa')}</span>}</article> })}</div>{paymentEdit && <form className="adm-editor" onSubmit={e => { e.preventDefault(); if (paymentEdit.enabled && (!paymentEdit.configured || !paymentEdit.validated)) { setError(t('Vérifie les instructions et confirme la procédure avant d’activer ce moyen de paiement.', 'Verifye enstriksyon yo epi konfime pwosedi a anvan ou aktive fason pou peye sa a.')); return } void act(() => savePayment(paymentEdit), () => setPaymentEdit(null)) }}>{editorHeading(paymentEdit.label)}<div className="adm-form-grid"><Field label={t('Instructions au client', 'Enstriksyon pou kliyan')} hint={t('Coordonnées de paiement, étapes et conditions de vérification.', 'Enfòmasyon pou peye, etap ak kondisyon verifikasyon.')}><textarea required minLength={5} maxLength={2000} rows={4} value={paymentEdit.instructions} onChange={e => setPaymentEdit({ ...paymentEdit, instructions: e.target.value })} /></Field><div className="adm-toggle-group"><Toggle checked={paymentEdit.enabled} onChange={enabled => setPaymentEdit({ ...paymentEdit, enabled })}>{t('Proposer ce moyen de paiement', 'Pwopoze fason pou peye sa a')}</Toggle><Toggle checked={paymentEdit.configured && paymentEdit.validated} onChange={checked => setPaymentEdit({ ...paymentEdit, configured: checked, validated: checked })}>{t('J’ai vérifié les instructions et validé cette procédure.', 'Mwen verifye enstriksyon yo epi mwen valide pwosedi sa a.')}</Toggle><p className="adm-help">{t('Les paiements manuels exigent toujours une vérification par l’administration.', 'Peman manyèl yo toujou mande verifikasyon administrasyon an.')}</p></div></div><div className="adm-form-actions">{submit()}</div></form>}</>}

    {tab === 'promotions' && <><div className="adm-section-heading"><div><h2>{t('Les bonnes affaires du Sud.', 'Bèl okazyon nan Sid.')}</h2><p>{t('Créez des codes de réduction avec une période de validité.', 'Kreye kòd rabè ak yon peryòd validite.')}</p></div><button className="adm-primary" onClick={() => setPromotionEdit({ id: crypto.randomUUID(), code: '', title_fr: '', title_ht: '', discount_percent: 10, active: false, starts_at: new Date().toISOString(), ends_at: new Date(Date.now() + 7 * 86400000).toISOString() })}><Plus size={17} />{t('Créer une promotion', 'Kreye yon pwomosyon')}</button></div>{promotionEdit && <form className="adm-editor" onSubmit={e => { e.preventDefault(); if (new Date(promotionEdit.ends_at) <= new Date(promotionEdit.starts_at)) { setError(t('La fin doit être postérieure au début.', 'Fen an dwe apre kòmansman an.')); return } void act(() => savePromotion(promotionEdit), () => setPromotionEdit(null)) }}>{editorHeading(t('Code promotionnel', 'Kòd pwomosyon'))}<div className="adm-form-grid"><Field label={t('Code', 'Kòd')}><input required minLength={3} maxLength={24} pattern="[A-Z0-9]+(?:-[A-Z0-9]+)*" value={promotionEdit.code} onChange={e => setPromotionEdit({ ...promotionEdit, code: e.target.value.toUpperCase().replaceAll(' ', '') })} /></Field><Field label={t('Réduction (%)', 'Rabè (%)')}><input required type="number" min="1" max="100" step="1" value={promotionEdit.discount_percent} onChange={e => setPromotionEdit({ ...promotionEdit, discount_percent: Number(e.target.value) })} /></Field><Field label={t('Titre français', 'Tit franse')}><input required maxLength={160} value={promotionEdit.title_fr} onChange={e => setPromotionEdit({ ...promotionEdit, title_fr: e.target.value })} /></Field><Field label={t('Titre créole', 'Tit kreyòl')}><input required maxLength={160} value={promotionEdit.title_ht} onChange={e => setPromotionEdit({ ...promotionEdit, title_ht: e.target.value })} /></Field><Field label={t('Début (heure locale du navigateur)', 'Kòmansman (lè lokal navigatè a)')}><input required type="datetime-local" value={localDateTime(promotionEdit.starts_at)} onChange={e => setPromotionEdit({ ...promotionEdit, starts_at: e.target.value ? new Date(e.target.value).toISOString() : '' })} /></Field><Field label={t('Fin (heure locale du navigateur)', 'Fen (lè lokal navigatè a)')}><input required type="datetime-local" value={localDateTime(promotionEdit.ends_at)} onChange={e => setPromotionEdit({ ...promotionEdit, ends_at: e.target.value ? new Date(e.target.value).toISOString() : '' })} /></Field><Toggle checked={promotionEdit.active} onChange={active => setPromotionEdit({ ...promotionEdit, active })}>{t('Activer le code', 'Aktive kòd la')}</Toggle></div><div className="adm-form-actions">{submit()}</div></form>}<section className="adm-panel"><div className="adm-table-scroll"><table><thead><tr><th>{t('Code / offre', 'Kòd / òf')}</th><th>{t('Réduction', 'Rabè')}</th><th>{t('Validité', 'Validite')}</th><th>{t('Statut', 'Eta')}</th><th /></tr></thead><tbody>{data.promotions.map(promotion => <tr key={promotion.id}><td><strong>{promotion.code}</strong><small>{lang === 'fr' ? promotion.title_fr : promotion.title_ht}</small></td><td>−{promotion.discount_percent}%</td><td><small>{new Date(promotion.starts_at).toLocaleDateString('fr-HT')} → {new Date(promotion.ends_at).toLocaleDateString('fr-HT')}</small></td><td><span className={`adm-badge ${promotion.active && new Date(promotion.ends_at) > new Date() && new Date(promotion.starts_at) <= new Date() ? 'success' : ''}`}>{!promotion.active ? t('Inactive', 'Inaktif') : new Date(promotion.ends_at) <= new Date() ? t('Expirée', 'Ekspire') : new Date(promotion.starts_at) > new Date() ? t('Programmée', 'Pwograme') : t('Active', 'Aktif')}</span></td><td><button className="adm-icon" onClick={() => setPromotionEdit({ ...promotion })} aria-label={`${t('Modifier', 'Modifye')} ${promotion.code}`}><Pencil size={16} /></button></td></tr>)}</tbody></table></div>{!data.promotions.length && <Empty text={t('Aucun code promotionnel pour le moment.', 'Poko gen kòd pwomosyon.')} />}</section></>}

    {tab === 'drivers' && <><div className="adm-section-heading"><div><h2>{t('L’équipe du dernier kilomètre.', 'Ekip ki fè dènye etap la.')}</h2><p>{t('Ajoutez vos livreurs pour leur affecter les commandes.', 'Ajoute livre ou yo pou bay yo kòmand yo.')}</p></div><button className="adm-primary" onClick={() => setDriverEdit({ id: crypto.randomUUID(), name: '', phone: '', active: true })}><Plus size={17} />{t('Ajouter un livreur', 'Ajoute yon livre')}</button></div>{driverEdit && <form className="adm-editor" onSubmit={e => { e.preventDefault(); void act(() => saveDriver(driverEdit), () => setDriverEdit(null)) }}>{editorHeading(t('Fiche livreur', 'Fich livre'))}<div className="adm-form-grid"><Field label={t('Nom', 'Non')}><input required maxLength={140} value={driverEdit.name} onChange={e => setDriverEdit({ ...driverEdit, name: e.target.value })} /></Field><Field label={t('Téléphone haïtien', 'Telefòn ayisyen')} hint="+509 3XXX XXXX"><input required type="tel" inputMode="tel" maxLength={25} value={driverEdit.phone} onChange={e => setDriverEdit({ ...driverEdit, phone: e.target.value })} /></Field><Toggle checked={driverEdit.active} onChange={active => setDriverEdit({ ...driverEdit, active })}>{t('Disponible pour les livraisons', 'Disponib pou livrezon')}</Toggle></div><div className="adm-form-actions">{submit()}</div></form>}<section className="adm-panel"><div className="adm-table-scroll"><table><thead><tr><th>{t('Livreur', 'Livre')}</th><th>{t('Téléphone', 'Telefòn')}</th><th>{t('Livraisons en cours', 'Livrezon an kou')}</th><th>{t('Statut', 'Eta')}</th><th /></tr></thead><tbody>{data.drivers.map(driver => <tr key={driver.id}><td><strong>{driver.name}</strong></td><td>{driver.phone}</td><td>{data.orders.filter(order => order.assigned_driver_id === driver.id && !['delivered', 'cancelled'].includes(order.status)).length}</td><td><span className={`adm-badge ${driver.active ? 'success' : ''}`}>{driver.active ? t('Actif', 'Aktif') : t('Inactif', 'Inaktif')}</span></td><td><button className="adm-icon" aria-label={`${t('Modifier', 'Modifye')} ${driver.name}`} onClick={() => setDriverEdit({ ...driver })}><Pencil size={16} /></button></td></tr>)}</tbody></table></div>{!data.drivers.length && <Empty text={t('Aucun livreur ajouté.', 'Poko gen livre.')} />}</section></>}

    {tab === 'settings' && settingsEdit && <><div className="adm-section-heading"><div><h2>{t('Votre boutique, vos coordonnées.', 'Boutik ou, enfòmasyon ou.')}</h2><p>{t('Ces informations sont utilisées dans la boutique et sur les factures.', 'Enfòmasyon sa yo sèvi nan boutik la ak sou fakti yo.')}</p></div></div><form className="adm-editor" onSubmit={e => { e.preventDefault(); if (settingsEdit.whatsapp && !/^(?:\+?509)?[234]\d{7}$/.test(settingsEdit.whatsapp.replace(/[\s().-]/g, ''))) { setError(t('Renseigne un numéro haïtien valide : +509 suivi de 8 chiffres commençant par 2, 3 ou 4.', 'Antre yon nimewo ayisyen ki valab : +509 ak 8 chif ki kòmanse ak 2, 3 oswa 4.')); return } if (settingsEdit.pickup_enabled && (!settingsEdit.pickup_address.trim() || !settingsEdit.pickup_hours.trim())) { setError(t('Renseigne l’adresse et les horaires avant d’activer le retrait.', 'Ranpli adrès ak lè yo anvan ou aktive vin pran.')); return } void act(() => saveSettings({ ...settingsEdit, whatsapp: settingsEdit.whatsapp ? normalizePhone(settingsEdit.whatsapp) : '' })) }}><h3>{t('Identité & contact', 'Idantite & kontak')}</h3><div className="adm-form-grid"><Field label={t('Nom de la boutique', 'Non boutik la')}><input required maxLength={100} value={settingsEdit.name} onChange={e => setSettingsEdit({ ...settingsEdit, name: e.target.value })} /></Field><Field label={t('Numéro WhatsApp', 'Nimewo WhatsApp')} hint={t('Modifiable à tout moment. Vide : aucun lien de contact affiché.', 'Ou ka chanje li nenpòt lè. Vid : pa gen lyen kontak.')}><input type="tel" inputMode="tel" placeholder="+509 3XXX XXXX" maxLength={25} value={settingsEdit.whatsapp} onChange={e => setSettingsEdit({ ...settingsEdit, whatsapp: e.target.value })} /></Field><Field label={t('Adresse de retrait aux Cayes', 'Adrès pou vin pran Okay')}><textarea rows={3} maxLength={1500} required={settingsEdit.pickup_enabled} value={settingsEdit.pickup_address} onChange={e => setSettingsEdit({ ...settingsEdit, pickup_address: e.target.value })} /></Field><Field label={t('Horaires de retrait', 'Lè pou vin pran')} hint={t('Précise les jours et les heures d’ouverture.', 'Presize jou ak lè ouvèti yo.')}><textarea rows={3} maxLength={1000} required={settingsEdit.pickup_enabled} value={settingsEdit.pickup_hours} onChange={e => setSettingsEdit({ ...settingsEdit, pickup_hours: e.target.value })} /></Field></div><div className="adm-settings-pickup"><span className="adm-zone-icon"><ShoppingBag size={21} /></span><div><h4>{t('Retrait en boutique', 'Vin pran nan boutik')}</h4><p>{t('Le retrait n’est proposé qu’après son activation et la saisie d’une adresse et d’horaires.', 'Opsyon vin pran an disponib sèlman apre aktivasyon, ak yon adrès ak lè ouvèti.')}</p><Toggle checked={settingsEdit.pickup_enabled} onChange={pickup_enabled => setSettingsEdit({ ...settingsEdit, pickup_enabled })}>{t('Autoriser le retrait en boutique', 'Pèmèt vin pran nan boutik')}</Toggle></div></div><div className="adm-form-actions">{submit()}</div></form>{!isConfigured && <section className="adm-reset-panel"><div><h3>{t('Réinitialiser la démonstration', 'Reyinisyalize demonstrasyon an')}</h3><p>{t('Efface uniquement les modifications et commandes de test de ce navigateur.', 'Efase sèlman chanjman ak kòmand tès ki nan navigatè sa a.')}</p></div><button className="adm-secondary" disabled={busy} onClick={() => { if (window.confirm(t('Effacer toutes les données de démonstration de ce navigateur ?', 'Efase tout done demonstrasyon ki nan navigatè sa a ?'))) void act(async () => { resetDemo() }) }}><RefreshCw size={16} />{t('Réinitialiser', 'Reyinisyalize')}</button></section>}</>}
    <footer className="adm-footer">DS STORE · {t('Pensé pour le Grand Sud.', 'Fèt pou Gran Sid la.')} <span>{isConfigured ? t('Accès réservé à l’administration', 'Aksè rezève pou administrasyon') : t('Données locales de démonstration', 'Done lokal demonstrasyon')}</span></footer>
    </main>
  </div>
}
